import { P as PosteriorStore } from '../types-BBe9hxUs.js';
export { A as ArmRecord, S as StoreSnapshot } from '../types-BBe9hxUs.js';

/**
 * Node file-backed posterior store.
 *
 * The default store lives in memory, which is enough for one process but loses every accumulated
 * posterior on restart. This adapter persists the whole store to a single JSON file and reloads it on
 * construction, so routing state survives restarts with no database. Writes are atomic: the snapshot is
 * written to a temporary file and renamed over the target, so a crash mid-write never corrupts the
 * store. This is the only entry point that touches a Node built-in (`node:fs`); the rest of BayesRoute
 * stays node-free. For higher throughput or sharing across processes, implement {@link PosteriorStore}
 * over SQLite, Postgres, or Redis instead; this file store is the zero-dependency reference.
 *
 * @packageDocumentation
 */

/** Options for {@link createFileStore}. */
interface FileStoreOptions {
    /** The JSON file path to load from and persist to. */
    readonly path: string;
    /** Pretty-print the persisted JSON. Off by default, for the smallest file. */
    readonly pretty?: boolean;
}
/**
 * Create a posterior store backed by a JSON file. Existing contents are loaded on creation; every write
 * is flushed atomically through a temporary file and a rename.
 *
 * @throws {@link BayesRouteError} with code `ERR_INVALID_INPUT` when the existing file is not a valid
 *   store snapshot.
 */
declare function createFileStore(pathOrOptions: string | FileStoreOptions): PosteriorStore;

export { type FileStoreOptions, PosteriorStore, createFileStore };
